class _ShopState extends State<_Shop> {List<dynamic> items=[];bool busy=false;@override void initState(){super.initState();load();}Future<void> load()async{try{final r=await widget.api.cosmetics(widget.userId);setState(()=>items=r);}catch(_){}}Future<void> buy(int id)async{setState(()=>busy=true);try{await widget.api.buyCosmetic(id,widget.userId);await load();await widget.onResult();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{setState(()=>busy=false);}}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(24),children:[Text('Cosmetics',style:Theme.of(c).textTheme.headlineSmall),if(items.isEmpty)const Text('No cosmetics seeded yet.'),...items.map((x)=>Card(child:ListTile(title:Text(x['name']),subtitle:Text('${x['price']} coins'),trailing:x['owned']==true?const Text('Owned'):FilledButton(onPressed:busy?null:()=>buy(x['id']),child:const Text('Buy')))))]);}
class _KeyDialog extends StatefulWidget { const _KeyDialog({required this.config,required this.initial,required this.onSaved}); final AppConfig config;final String initial;final void Function(String) onSaved;@override State<_KeyDialog> createState()=>_KeyDialogState(); }
class _KeyDialogState extends State<_KeyDialog>{late String provider;final key=TextEditingController();@override void initState(){super.initState();provider=widget.initial;}@override Widget build(BuildContext c)=>AlertDialog(title:const Text('LLM API key'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButton<String>(value:provider,items:widget.config.providers.map((p)=>DropdownMenuItem(value:p,child:Text(p))).toList(),onChanged:(v)=>setState(()=>provider=v!)),TextField(controller:key,obscureText:true,decoration:const InputDecoration(hintText:'Stored only in secure storage'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:()async{if(key.text.isNotEmpty)await SecureKeys.saveLlmApiKey(provider,key.text);widget.onSaved(provider);if(mounted)Navigator.pop(c);},child:const Text('Save'))]);}
